let cnpjLength = 14

let invalidCNPJs = [
  "00000000000000",
  "11111111111111",
  "22222222222222",
  "33333333333333",
  "44444444444444",
  "55555555555555",
  "66666666666666",
  "77777777777777",
  "88888888888888",
  "99999999999999",
]

let isNumeric = str => %re("/^\d*$/")->RegExp.test(str)
let isUppercaseAlphanumeric = str => %re("/^[A-Z0-9]*$/")->RegExp.test(str)

// A valid CNPJ must have alphanumeric (A-Z / 0-9) characters in the first 12
// positions and strictly numeric digits in the last 2 (check digit) positions.
let isCNPJValidFormat = cnpj => {
  let base = cnpj->String.slice(~start=0, ~end=12)
  let checkDigits = cnpj->String.slice(~start=12, ~end=14)
  isUppercaseAlphanumeric(base) && isNumeric(checkDigits)
}

// Convert a single character to its CNPJ numeric value.
// '0'–'9'  →  0–9   (ASCII code − 48 - 57)
// 'A'–'Z'  →  17–42 (ASCII code − 65 - 90)
let charToValue = ch => {
  let code = ch->String.charCodeAt(0)->Float.toInt
  if code >= 48 && code <= 57 {
    code - 48
  } else if code >= 65 && code <= 90 {
    code - 48
  } else {
    0
  }
}

// Calculate a single CNPJ check digit from value and weight arrays.
// sum = Σ values[i] × weights[i];  remainder = sum mod 11
// result = remainder < 2 ? 0 : 11 − remainder
let calculateCheckDigit = (values: array<int>, weights: array<int>) => {
  let sum = values->Array.reduceWithIndex(0, (acc, v, i) => {
    acc + v * weights->Array.get(i)->Option.getOr(0)
  })
  let remainder = mod(sum, 11)
  remainder < 2 ? 0 : 11 - remainder
}

// Validate a CNPJ (numeric or alphanumeric) using the Modulo-11 algorithm.
// Each character is mapped to an integer via charToValue before computation.
// Works for both the classic all-digit format and the new alphanumeric format.
let validateCNPJ = cnpj => {
  let chars = cnpj->String.split("")
  let base = chars->Array.slice(~start=0, ~end=12)->Array.map(charToValue)

  let firstDigit = calculateCheckDigit(base, [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2])
  let secondDigit = calculateCheckDigit(
    [...base, firstDigit],
    [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2],
  )

  let checkDigit1 = chars->Array.get(12)->Option.map(charToValue)->Option.getOr(-1)
  let checkDigit2 = chars->Array.get(13)->Option.map(charToValue)->Option.getOr(-1)

  firstDigit === checkDigit1 && secondDigit === checkDigit2
}

let isValidCNPJ = cnpj => {
  if (
    cnpj->String.length !== cnpjLength ||
    invalidCNPJs->Array.includes(cnpj) ||
    !isCNPJValidFormat(cnpj)
  ) {
    false
  } else {
    validateCNPJ(cnpj)
  }
}

open CountryStateDataHookTypes

let formatPhoneNumber = (phoneNumberText, countries) => {
  if phoneNumberText == "" || phoneNumberText->String.length > 20 {
    ("", phoneNumberText)
  } else {
    let startsAt =
      phoneNumberText->String.search(%re("/[+\uFF0B0-9\uFF10-\uFF19\u0660-\u0669\u06F0-\u06F9]/"))

    if startsAt < 0 {
      ("", phoneNumberText)
    } else {
      let cleanNumber =
        phoneNumberText
        ->String.sliceToEnd(~start=startsAt)
        ->String.replaceRegExp(%re("/[^0-9\uFF10-\uFF19\u0660-\u0669\u06F0-\u06F9#]+$/"), "")

      if (
        cleanNumber->String.length < 2 ||
          !(cleanNumber->String.match(%re("/[0-9]/"))->Option.isSome)
      ) {
        ("", phoneNumberText)
      } else {
        let hasPlus = cleanNumber->String.indexOf("+") !== -1
        let digits = cleanNumber->String.replaceRegExp(%re("/[^0-9]/g"), "")

        let (countryCode, nationalNumber) = if hasPlus {
          let rec findCode = (i, digits, countries) => {
            if i > 3 || i > digits->String.length {
              ("", digits)
            } else {
              let code = digits->String.slice(~start=0, ~end=i)
              let found = countries->Array.find(country => {
                country.phone_number_code === `+${code}`
              })

              found->Option.isSome
                ? (code, digits->String.sliceToEnd(~start=i))
                : findCode(i + 1, digits, countries)
            }
          }
          findCode(1, digits, countries)
        } else {
          ("", digits)
        }

        if hasPlus && countryCode == "" {
          // ||
          // nationalNumber->String.length < 2 ||
          // nationalNumber->String.length > 17
          ("", phoneNumberText)
        } else if countryCode == "" {
          ("", nationalNumber)
        } else {
          (`+${countryCode}`, nationalNumber)
        }
      }
    }
  }
}

let cpfLength = 11

let invalidCPFs = [
  "00000000000",
  "11111111111",
  "22222222222",
  "33333333333",
  "44444444444",
  "55555555555",
  "66666666666",
  "77777777777",
  "88888888888",
  "99999999999",
]

let isValidCPFFormat = (cpf: string) => {
  %re("/^\d*$/")->RegExp.test(cpf) &&
  cpf->String.length === cpfLength &&
  !(invalidCPFs->Array.includes(cpf))
}

let calculateCheckDigit = numbers => {
  let weight = numbers->Array.length + 1
  let sum = numbers->Array.reduceWithIndex(0, (acc, num, index) => {acc + num * (weight - index)})
  let remainder = mod(sum, 11)
  remainder < 2 ? 0 : 11 - remainder
}

let isValidCPF = (cpf: string) => {
  open CardValidations
  if !isValidCPFFormat(cpf) {
    false
  } else {
    let digits = cpf->String.split("")->Array.map(s => s->toInt)
    let baseCPF = digits->Array.slice(~start=0, ~end=9)

    let firstDigit = calculateCheckDigit(baseCPF)
    let secondDigit = calculateCheckDigit([...baseCPF, firstDigit])

    firstDigit === digits->Array.get(9)->Option.getOr(-1) &&
      secondDigit === digits->Array.get(10)->Option.getOr(-1)
  }
}

let toInt = val => val->Int.fromString->Option.getOr(0)

let getobjFromCardPattern = cardBrand => {
  let patternsDict = CardPattern.cardPatterns
  patternsDict
  ->Array.filter(item => {
    cardBrand === item.issuer
  })
  ->Array.get(0)
  ->Option.getOr(CardPattern.defaultCardPattern)
}

let clearSpaces = value => {
  value->String.replaceRegExp(%re("/\D+/g"), "")
}

let slice = (val, start: int, end: int) => {
  val->String.slice(~start, ~end)
}

let getAllMatchedCardSchemes = cardNumber => {
  CardPattern.cardPatterns->Array.reduce([], (acc, item) => {
    if String.match(cardNumber, item.pattern)->Option.isSome {
      acc->Array.push(item.issuer)
    }
    acc
  })
}

let isCardSchemeEnabled = (~cardScheme, ~enabledCardSchemes) => {
  enabledCardSchemes->Array.includes(cardScheme)
}

let formatCVCNumber = (val, cardType) => {
  let clearValue = val->clearSpaces
  let obj = getobjFromCardPattern(cardType)
  clearValue->slice(0, obj.maxCVCLength)
}

let getStrFromIndex = (arr: array<string>, index) => {
  arr->Array.get(index)->Option.getOr("")
}

let splitExpiryDates = val => {
  let split = val->String.split("/")
  let value = split->Array.map(item => item->String.trim)
  let month = value->Array.get(0)->Option.getOr("")
  let year = value->Array.get(1)->Option.getOr("")
  (month, year)
}

let formatCardExpiryNumber = val => {
  let clearValue = val->clearSpaces
  let expiryVal = clearValue->toInt
  let formatted = if expiryVal >= 2 && expiryVal <= 9 && clearValue->String.length == 1 {
    `0${clearValue} / `
  } else if clearValue->String.length == 2 && expiryVal > 12 {
    let val = clearValue->String.split("")
    `0${val->getStrFromIndex(0)} / ${val->getStrFromIndex(1)}`
  } else {
    clearValue
  }

  if clearValue->String.length >= 3 {
    `${formatted->slice(0, 2)} / ${formatted->slice(2, 4)}`
  } else {
    formatted
  }
}

type cardIssuer =
  | VISA
  | MASTERCARD
  | AMEX
  | MAESTRO
  | DINERSCLUB
  | DISCOVER
  | BAJAJ
  | SODEXO
  | RUPAY
  | JCB
  | CARTESBANCAIRES
  | NOTFOUND

let cardType = val => {
  switch val->String.toUpperCase {
  | "VISA" => VISA
  | "MASTERCARD" => MASTERCARD
  | "AMEX" => AMEX
  | "MAESTRO" => MAESTRO
  | "DINERSCLUB" => DINERSCLUB
  | "DISCOVER" => DISCOVER
  | "BAJAJ" => BAJAJ
  | "SODEXO" => SODEXO
  | "RUPAY" => RUPAY
  | "JCB" => JCB
  | "CARTESBANCAIRES" => CARTESBANCAIRES
  | _ => NOTFOUND
  }
}

let formatCardNumber = (val, cardType) => {
  let clearValue = val->clearSpaces
  let formatedCard = switch cardType {
  | AMEX => `${clearValue->slice(0, 4)} ${clearValue->slice(4, 10)} ${clearValue->slice(10, 15)}`
  | DINERSCLUB =>
    if clearValue->String.length > 14 {
      `${clearValue->slice(0, 4)} ${clearValue->slice(4, 8)} ${clearValue->slice(
          8,
          12,
        )} ${clearValue->slice(12, 16)}   ${clearValue->slice(16, 19)}`
    } else {
      `${clearValue->slice(0, 4)} ${clearValue->slice(4, 10)} ${clearValue->slice(10, 14)}`
    }
  | MASTERCARD
  | DISCOVER
  | SODEXO
  | RUPAY
  | VISA =>
    `${clearValue->slice(0, 4)} ${clearValue->slice(4, 8)} ${clearValue->slice(
        8,
        12,
      )} ${clearValue->slice(12, 16)} ${clearValue->slice(16, 19)}`
  | _ =>
    `${clearValue->slice(0, 4)} ${clearValue->slice(4, 8)} ${clearValue->slice(
        8,
        12,
      )} ${clearValue->slice(12, 19)}`
  }

  formatedCard->String.trim
}

