  issuer: "",
  pattern: %re("/^[0-9]/"),
  cvcLength: [3, 4],
  maxCVCLength: 4,
  length: [13, 14, 15, 16, 17, 18, 19],
  pincodeRequired: false,
}

let cardPatterns = [
  {
    issuer: "Maestro",
    pattern: %re(
