  let trimmedText = text->String.trim
  let isIbanEmpty = trimmedText->String.length != 0
  isIbanEmpty
}

let formatCardNumber = (val, cardType) => {
  let clearValue = val->clearSpaces
  let formatedCard = switch cardType {
  | AMEX => `${clearValue->slice(0, 4)} ${clearValue->slice(4, 10)} ${clearValue->slice(10, 15)}`
  | DINERSCLUB =>
    if clearValue->String.length > 14 {
      `${clearValue->slice(0, 4)} ${clearValue->slice(4, 8)} ${clearValue->slice(
          8,
          12,
        )} ${clearValue->slice(12, 16)}   ${clearValue->slice(16, 19)}`
    } else {
      `${clearValue->slice(0, 4)} ${clearValue->slice(4, 10)} ${clearValue->slice(10, 14)}`
    }
  | MASTERCARD
  | DISCOVER
  | SODEXO
  | RUPAY
  | VISA =>
    `${clearValue->slice(0, 4)} ${clearValue->slice(4, 8)} ${clearValue->slice(
        8,
        12,
      )} ${clearValue->slice(12, 16)} ${clearValue->slice(16, 19)}`
  | _ =>
    `${clearValue->slice(0, 4)} ${clearValue->slice(4, 8)} ${clearValue->slice(
        8,
        12,
      )} ${clearValue->slice(12, 19)}`
  }

  formatedCard->String.trim
}

let formatCVCNumber = (val, cardType) => {
  let clearValue = val->clearSpaces
  let obj = getobjFromCardPattern(cardType)
  clearValue->slice(0, obj.maxCVCLength)
}

let formatCardExpiryNumber = val => {
  let clearValue = val->clearSpaces
  let expiryVal = clearValue->toInt
  let formatted = if expiryVal >= 2 && expiryVal <= 9 && clearValue->String.length == 1 {
    `0${clearValue} / `
  } else if clearValue->String.length == 2 && expiryVal > 12 {
    let val = clearValue->String.split("")
    `0${val->getStrFromIndex(0)} / ${val->getStrFromIndex(1)}`
  } else {
    clearValue
  }

  if clearValue->String.length >= 3 {
    `${formatted->slice(0, 2)} / ${formatted->slice(2, 4)}`
  } else {
    formatted
  }
}

let isAtLeast18YearsOld = value => {
  switch value->String.split("-") {
  | [year, month, date] => {
      let dob = Date.makeWithYMD(~year=year->toInt, ~month=month->toInt - 1, ~date=date->toInt)
      let now = Date.make()
      let threshold = Date.makeWithYMD(
        ~year=now->Date.getFullYear - 18,
        ~month=now->Date.getMonth,
        ~date=now->Date.getDate,
      )
      dob->Date.getTime <= threshold->Date.getTime
    }
  | _ => false
  }
}

let validateField = (
  value: string,
  rules: array<validationRule>,
  ~enabledCardSchemes: array<string>,
  ~localeObject: LocaleDataType.localeStrings,
) => {
  rules->Array.reduce(None, (acc, rule) => {
    switch acc {
    | Some(_) => acc
    | None =>
      switch rule {
      | Required(customMessage) => {
          let trimmedValue = value->String.trim
          if trimmedValue === "" {
            Some(customMessage->Option.getOr(localeObject.mandatoryFieldText))
          } else {
            None
          }
        }
      | MinLength(min) =>
        if value->String.length < min {
          Some(`Minimum ${min->Int.toString} characters required`)
        } else {
          None
        }
      | MaxLength(max) =>
        if value->String.length > max {
          Some(`Maximum ${max->Int.toString} characters allowed`)
        } else {
          None
        }
      | CardNumber =>
        if value->String.length === 0 {
          Some(localeObject.cardNumberEmptyText)
        } else {
          let validCardBrand = getFirstValidCardScheme(~cardNumber=value, ~enabledCardSchemes)
          let cardBrand = validCardBrand === "" ? getCardBrand(value) : validCardBrand
          let formattedNumber = formatCardNumber(value, cardType(cardBrand))
          cardValid(formattedNumber, cardBrand) ? None : Some(localeObject.inValidCardErrorText)
        }
      | CardExpiry(value) =>
        if value->String.length === 0 {
          Some(localeObject.cardExpiryDateEmptyText)
        } else if checkCardExpiry(value) {
          None
        } else {
          Some(localeObject.inValidExpiryErrorText)
        }
      | CardCVC(cardBrand) =>
        if value->String.length === 0 {
          Some(localeObject.cvcNumberEmptyText)
        } else if checkCardCVC(value, cardBrand) {
          None
        } else {
          Some(localeObject.inValidCVCErrorText)
        }
      | CardNetwork(enabledCardSchemes) =>
        enabledCardSchemes->Array.find(v => v === value)->Option.isSome
          ? None
          : Some(localeObject.unsupportedCardErrorText)
      | Email =>
        if value->String.length === 0 {
          Some(localeObject.emailEmptyText)
        } else {
          switch value->isEmailValid {
          | Some(true) => None
          | Some(false) => Some(localeObject.emailInvalidText)
          | None => None
          }
        }
      | FirstName => {
          let trimmedValue = value->String.trim
          if trimmedValue->String.length < 1 {
            Some(localeObject.cardHolderNameRequiredText)
          } else if containsDigit(trimmedValue) {
            Some(localeObject.invalidDigitsCardHolderNameError)
          } else {
            None
          }
        }
      | LastName => {
          let trimmedValue = value->String.trim
          if trimmedValue->String.length < 1 {
            Some(localeObject.lastNameRequiredText)
          } else if containsDigit(trimmedValue) {
            Some(localeObject.invalidDigitsCardHolderNameError)
          } else {
            None
          }
        }
      | Phone => {
          let cleanPhone = value->clearSpaces
          if cleanPhone->String.length < 10 {
            Some(localeObject.phoneInvalidText)
          } else {
            None
          }
        }
      | PostalCode(country) =>
        isValidZip(~zipCode=value, ~country) ? None : Some(localeObject.postalCodeInvalidText)
      | BankAccountNumber => {
          let cleanValue = value->clearSpaces
          if cleanValue->String.length === 0 {
            Some(localeObject.mandatoryFieldText)
          } else if !containsOnlyDigits(cleanValue) {
            Some(localeObject.accountNumberInvalidText)
          } else if cleanValue->String.length > 17 {
            Some(localeObject.accountNumberInvalidText)
          } else {
            None
          }
        }
      | IBAN => isValidIban(value) ? None : Some(localeObject.ibanEmptyText)
      | BlikCode => {
          let digits = value->String.replaceRegExp(%re("/[^0-9]/g"), "")
          if value->String.length === 0 {
            Some(localeObject.mandatoryFieldText)
          } else if digits->String.length !== 6 {
            Some(localeObject.blikCodeInvalidText)
          } else {
            None
          }
        }
      | GiftCardNumber => value->String.length === 0 ? Some(localeObject.mandatoryFieldText) : None
      | GiftCardPin => value->String.length === 0 ? Some(localeObject.mandatoryFieldText) : None
      | Nickname => {
          let digitMatches = value->String.match(%re("/\d/g"))
          let digitCount = switch digitMatches {
          | Some(arr) => arr->Array.length
          | None => 0
          }
          if digitCount > 2 {
            Some(localeObject.invalidNickNameError)
          } else {
            None
          }
        }
      | PixKey =>
        if value->String.length > 0 {
          None
        } else {
          Some(localeObject.pixKeyEmptyText)
        }
      | PixCPF => {
          let isCPFValid = CpfValidation.isValidCPF(value)
          if isCPFValid {
            None
          } else if value->String.length === 0 {
            Some(localeObject.pixCPFEmptyText)
          } else {
            Some(localeObject.pixCPFInvalidText)
          }
        }
      | PixCNPJ => {
          let isCNPJValid = CnpjValidation.isValidCNPJ(value)
          if isCNPJValid {
            None
          } else if value->String.length === 0 {
            Some(localeObject.pixCNPJEmptyText)
          } else {
            Some(localeObject.pixCNPJInvalidText)
          }
        }
      | RoutingNumber => {
          let cleanValue = value->clearSpaces
          if cleanValue->String.length === 0 {
            Some(localeObject.mandatoryFieldText)
          } else if cleanValue->String.length !== 9 {
            Some(localeObject.formFieldInvalidRoutingNumber)
          } else if !containsOnlyDigits(cleanValue) {
            Some(localeObject.formFieldInvalidRoutingNumber)
          } else {
            let firstWeight = 3
            let weights = [firstWeight, 7, 1, 3, 7, 1, 3, 7, 1]
            let sum =
              cleanValue
              ->String.split("")
              ->Array.mapWithIndex((item, i) => item->toInt * weights[i]->Option.getOr(firstWeight))
              ->Array.reduce(0, (acc, val) => acc + val)
            if mod(sum, 10) == 0 {
              None
            } else {
              Some(localeObject.formFieldInvalidRoutingNumber)
            }
          }
        }
      | DateOfBirth =>
        if value->String.trim->String.length === 0 {
          Some(localeObject.dateofBirthRequiredText)
        } else if isAtLeast18YearsOld(value) {
          None
        } else {
          Some(localeObject.dateOfBirthInvalidText)
        }
      | Generic(pattern) =>
        if value === "" {
          None
        } else {
          try {
            let re = RegExp.fromString(pattern)
            re->RegExp.test(value) ? None : Some(localeObject.enterValidDetailsText)
          } catch {
          | _ => {
              Console.warn(
                `Invalid regex pattern in Generic validator: "${pattern}", needs to be fixed for proper validation.`,
              )
              None
            }
