  | "classic" => "Cash / Voucher"
  | "evoucher" => "E-Voucher"
  | "ach" | "sepa" | "bacs" | "becs" => text ++ " Debit"
  | "ideal" => "iDEAL | Wero"
  | "open_banking" => "Pay By Bank"
  | other => other
  }

  let capitalizeWord = str =>
    switch str->String.get(0) {
    | Some(firstChar) => firstChar->String.toUpperCase ++ str->String.sliceToEnd(~start=1)
    | None => str
    }

  transformText
  ->String.split("_")
  ->Array.map(capitalizeWord)
  ->Array.join(" ")
}

open SuperpositionHelper

type configurationService = {
  evaluateConfig: SuperpositionTypes.superpositionContext => Dict.t<JSON.t>,
}

@module("./../superposition/superposition.js") @new
external cacReader: JSON.t => Nullable.t<configurationService> = "CacReader"

let useConfigurationService = (~rawConfigs: option<JSON.t>) => {
  let service = React.useMemo(() => {
    switch rawConfigs {
    | None => None
    | Some(configData) => cacReader(configData)->Nullable.toOption
    }
  }, [rawConfigs])

  React.useCallback(
    (
      eligibleConnectors: array<RescriptCore.JSON.t>,
      configParams: SuperpositionTypes.superpositionBaseContext,
      intentData: JSON.t,
      ~isUseBillingAddress=false,
      ~suppressBillingPrefill=false,
    ) => {
      let intentDataDict = intentData->CommonUtils.getDictFromJson
      let requiredFieldsFromSuperPosition = switch (
        service,
        Array.length(eligibleConnectors) === 0,
      ) {
      | (_, true)
      | (None, false) => []
      | (Some(svc), false) =>
        eligibleConnectors
        ->removeDuplicateConnectors
        ->Array.reduce([], (acc, connector) => {
          try {
            switch connector->JSON.Decode.string {
            | Some("") | None => ()
            | Some(connector) =>
              let transformedContext: SuperpositionTypes.superpositionContext = {
                connector,
                payment_method: configParams.payment_method->CommonUtils.snakeToPascalCase,
                payment_method_type: configParams.payment_method_type->CommonUtils.snakeToPascalCase,
                country: configParams.country,
                currency: ?configParams.currency,
                mandate_type: configParams.mandate_type,
                always_collect_billing_details_from_wallet_connector: configParams.always_collect_billing_details_from_wallet_connector,
                always_collect_shipping_details_from_wallet_connector: configParams.always_collect_shipping_details_from_wallet_connector,
                platform: configParams.platform,
                profile_id: ?configParams.profile_id,
                processor_merchant_id: ?configParams.processor_merchant_id,
                provider_merchant_id: ?configParams.provider_merchant_id,
                organization_id: ?configParams.organization_id,
              }
              let resolvedConfig =
                svc.evaluateConfig(transformedContext)->convertConfigurationToRequiredFields(
                  ~isUseBillingAddress,
                )
              acc->Array.pushMany(resolvedConfig)
            }
          } catch {
          | _ => ()
          }
          acc
        })
        ->removeDuplicateFields
        ->sortFieldsByPriorityOrder
      }

      let missingRequiredFields = filterFieldsBasedOnMissingData(
        requiredFieldsFromSuperPosition,
        intentDataDict,
        ~isUseBillingAddress,
      )

      let fieldsToRender = getFieldsToRender(requiredFieldsFromSuperPosition, missingRequiredFields)

      let initialValues =
        buildInitialValuesFromIntentData(
          requiredFieldsFromSuperPosition,
          intentDataDict,
          ~suppressBillingPrefill,
        )->convertFlatDictToNestedObject

      (requiredFieldsFromSuperPosition, fieldsToRender, initialValues)
    },
    [service],
  )
}

